#!/bin/sh
# Stop on NOP-filled processor: the program zeroes its own instruction
# area and stops. Program: (3032,0,DATA) input 3008 bits (the program
# size), (31,DATA,0x3000) output 8 bits, 62 NOPs; then 376 zero stream
# bytes (3008 bits). DATA is the position after the space. An input of
# 3008 data bits uses n = 3008 + (1 + 8 + 15) = 3032 at -s 65520.
# Tick 1 loads the program (silence); tick 2 inputs zeros over the
# instruction area and outputs one zero byte from 0x3000; tick 3: all
# n are zero, stop. Outward: a single zero byte.
set -e
cd "$(dirname "$0")/.."
if [ ! -x ./space ]; then
  echo "no ./space, run make first"
  exit 1
fi
{ printf '\033\320\000\000\037\377\360\000\077\374\000\060\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000\000'; head -c 376 /dev/zero; } | timeout 5 ./space > /tmp/stop_run.out
printf '\000' > /tmp/stop_expected.out
cmp /tmp/stop_run.out /tmp/stop_expected.out
echo "ok: NOP stop (single zero byte)"
